"""**2) Leitura das bases de treino e validação**

Define os caminhos e lê os datasets *dataset_train_2014_2020.csv* e *dataset_val_2021_2022.csv*, gerados na etapa de EDA.
Assim, os dados de treino e validação ficarão carregados em memória para uso no modelo.
"""

caminho_val    = "/content/drive/MyDrive/Projeto Aplicado 4/dataset_val_2021_2022.csv"
caminho_treino = "/content/drive/MyDrive/Projeto Aplicado 4/dataset_train_2014_2020.csv"

"""**3) Definição de hiperparâmetros, chaves e leitura das bases de dados**

Definir os parâmetros temporais do modelo, as chaves de agrupamento das séries e as colunas usadas como variáveis.
Em seguida, realizar a leitura das bases de treino e validação e converte o ano do censo para formato numérico, preparando os dados para o pré-processamento e modelagem.
"""

# Hiperparâmetros de série
HISTORY_WINDOW = 3   # anos de histórico usados como entrada
FORECAST_H     = 1   # horizonte de previsão (1 ano à frente)

# Chaves de definição para cada série temporal
GROUP_KEYS = ["CO_IES", "CO_CINE_ROTULO_id", "Modalidade"]

# Colunas contínuas e categóricas
CONT_COLS = [
    "QT_MAT", "QT_ING", "QT_ING_FEM", "QT_ING_MASC",
    "QT_SIT_TRANCADA", "QT_SIT_DESVINCULADO", "QT_SIT_TRANSFERIDO", "QT_SIT_FALECIDO",
    "QT_ING_PROCESCPUBLICA", "QT_ING_PROCESCPRIVADA"
]
CAT_COLS = [
    "Modalidade", "Rede", "CO_REGIAO", "CO_UF", "CO_MUNICIPIO", "CO_CINE_ROTULO_id"
]

#  Leitura dos dois arquivos (treino e validação)
df_train_raw = pd.read_csv(caminho_treino, low_memory=False)
df_val_raw   = pd.read_csv(caminho_val,    low_memory=False)

# Garantir tipo numérico do ano
for dfx in (df_train_raw, df_val_raw):
    dfx["NU_ANO_CENSO"] = pd.to_numeric(dfx["NU_ANO_CENSO"], errors="coerce")

"""**4) Criação da métrica de evasão e definição da variável-alvo (*TAXA_EVASAO*)**

Criação da função *add_evasao_cols()* que calculará a variável *TAXA_EVASAO* com base na soma de *QT_SIT_TRANCADA*, *QT_SIT_DESVINCULADO*, *QT_SIT_TRANSFERIDO* e *QT_SIT_FALECIDO*, dividida por *QT_MAT*.
A função removerá registros com *QT_MAT* igual a zero, aplica-se em *df_train_raw* e *df_val_raw*, e ao final exibirá os anos presentes em cada base
"""

# Criar métrica de evasão e alvo TAXA_EVASAO
def add_evasao_cols(dfx: pd.DataFrame) -> pd.DataFrame:
    dfx = dfx.copy()
    dfx["QT_EVASAO_TOTAL"] = (
        dfx["QT_SIT_TRANCADA"].fillna(0) +
        dfx["QT_SIT_DESVINCULADO"].fillna(0) +
        dfx["QT_SIT_TRANSFERIDO"].fillna(0) +
        dfx["QT_SIT_FALECIDO"].fillna(0)
    )
    dfx = dfx[dfx["QT_MAT"] > 0].copy()  # evita divisão por zero
    dfx["TAXA_EVASAO"] = dfx["QT_EVASAO_TOTAL"] / dfx["QT_MAT"]
    return dfx

df_train_raw = add_evasao_cols(df_train_raw)
df_val_raw   = add_evasao_cols(df_val_raw)

print("Anos treino:", sorted(df_train_raw["NU_ANO_CENSO"].unique().tolist()))
print("Anos validação:", sorted(df_val_raw["NU_ANO_CENSO"].unique().tolist()))

"""**5) Normalização das variáveis contínuas (fit no treino e aplicação na validação)**

Normalização das variáveis contínuas (*CONT_COLS*) usando StandardScaler, ajustando a escala com base no conjunto de treino (*df_train_raw*) e aplicando o mesmo padrão ao conjunto de validação (*df_val_raw*).
A função *apply_scaling()* criará cópias dos DataFrames e substitui as colunas normalizadas, resultando em *df_train* e *df_val* prontos para a modelagem.
"""

#  Normalização (fit no TREINO; aplicar no VAL)
# Filtra CONT_COLS existentes
CONT_COLS = [c for c in CONT_COLS if c in df_train_raw.columns and c in df_val_raw.columns]

scaler = StandardScaler()
scaler.fit(df_train_raw[CONT_COLS])

def apply_scaling(dfx: pd.DataFrame) -> pd.DataFrame:
    dfx2 = dfx.copy()
    dfx2[CONT_COLS] = scaler.transform(dfx2[CONT_COLS])
    return dfx2

df_train = apply_scaling(df_train_raw)
df_val   = apply_scaling(df_val_raw)

"""**6) Seleção final das variáveis preditoras (FEATURES)**

Definir a lista *FEATURES*, unindo as variáveis contínuas (*CONT_COLS*) e categóricas (*CAT_COLS*) que serão usadas pelo modelo.
Em seguida, filtrará a lista para garantir que todas as colunas selecionadas existam tanto em *df_train* quanto em *df_val*, evitando erros nas etapas de treinamento e validação.
"""

# Seleção final de FEATURES
FEATURES = CONT_COLS + CAT_COLS
# Garante que todas existam
FEATURES = [c for c in FEATURES if c in df_train.columns and c in df_val.columns]

"""**7) Função para criação de janelas temporais (sequências de entrada e alvo)**

Definir a função *build_sequences()*, responsável por gerar as amostras de treino e validação no formato de janelas deslizantes de tempo.
A função percorrerá cada série temporal definida pelas *group_keys*, utilizando *history_window* anos de histórico para prever o valor da variável-alvo (*TAXA_EVASAO*) no horizonte de *forecast_h* anos à frente.

Serão retornada três listas:

*   *X_list*: matrizes com as janelas históricas de entrada;
*   *y_list*: valores alvo correspondentes;
*   *meta_list*: informações auxiliares (ano previsto e identificadores da série).
"""

# Função para criar sequências (janelas)
from tqdm.auto import tqdm # Importar tqdm

def build_sequences(df_all_history: pd.DataFrame,
                    df_target_years: pd.DataFrame,
                    history_window: int,
                    forecast_h: int,
                    group_keys: list,
                    features: list):
    """
    Cria amostras (X, y) por janelas deslizantes, por série temporal (group_keys).
    - df_all_history: histórico disponível (para construir o passado da série)
    - df_target_years: subconjunto que define em quais anos o alvo deve cair
    - history_window: tamanho da janela de entradas (ex.: 3 anos)
    - forecast_h: horizonte de previsão (ex.: 1 ano à frente)
    - features: colunas de entrada (numéricas + categóricas já numerificadas)

    Retorna:
      X_list: [N, history_window, num_features]
      y_list: [N]
      meta_list: lista de dicts com 'target_year' e 'group_keys'
    """
    X_list, y_list, meta_list = [], [], []
    target_years_set = set(df_target_years["NU_ANO_CENSO"].unique().tolist())

    # Agrupamento por entidade da série
    # Adicionar tqdm para a barra de progresso
    grouped = df_all_history.groupby(group_keys)
    for keys, g in tqdm(grouped, desc="Building sequences"):
        g = g.sort_values("NU_ANO_CENSO")
        n = len(g)
        if n < history_window + forecast_h:
            continue

        for end_idx in range(history_window, n - forecast_h + 1):
            start_hist = end_idx - history_window
            # histórico (janela)
            x_hist = g.iloc[start_hist:end_idx][features].values.astype(np.float32)

            # alvo (no passo end_idx + forecast_h - 1)
            target_row = g.iloc[end_idx + (forecast_h - 1)]
            target_year = int(target_row["NU_ANO_CENSO"])
            if target_year not in target_years_set:
                continue

            y = float(target_row["TAXA_EVASAO"])

            X_list.append(x_hist)
            y_list.append(y)
            meta_list.append({
                "target_year": target_year,
                "group_keys": keys
            })

    return X_list, y_list, meta_list

"""**8) Geração das sequências de treinamento (janelas históricas e alvos)**

Criae as sequências de entrada e saída do conjunto de treino utilizando a função *build_sequences()*.
Ela identifica o último ano presente em *df_train* (*latest_year_train*) e, a partir do histórico contido no próprio conjunto de treino, constrói amostras (*X_train*, *y_train*, *meta_train*) com:



*   entradas (*X_train*) correspondendo às janelas de *HISTORY_WINDOW* anos;
*   alvos (*y_train*) definidos pelo ano seguinte (*FORECAST_H* = 1);
*   metadados (*meta_train*) contendo o ano previsto e as chaves de agrupamento (*GROUP_KEYS*).

Essas sequências serão utilizadas para treinar o modelo nas próximas etapas.
"""

# Criar sequências para TREINO e VALIDAÇÃO
# Para TREINO: alvos dentro do período de treino, histórico = próprio treino
latest_year_train = df_train["NU_ANO_CENSO"].max()
# df_train_filtered = df_train[df_train["NU_ANO_CENSO"] >= latest_year_train - 3] # Últimos 4 anos (ano atual - 3 anos anteriores)


X_train, y_train, meta_train = build_sequences(
    df_all_history=df_train, # Usar dados filtrados
    df_target_years=df_train, # Alvos também nos anos filtrados
    history_window=HISTORY_WINDOW,
    forecast_h=FORECAST_H,
    group_keys=GROUP_KEYS,
    features=FEATURES
)

"""**9) Verificação dos anos disponíveis no conjunto de treino**

Exibir os anos únicos presentes no DataFrame de treino (*df_train*), permitindo confirmar se o período temporal está correto e consistente com o intervalo esperado (por exemplo, 2014–2020).
Utilizada como checagem rápida de integridade antes da geração das janelas temporais e do treinamento do modelo.
"""

print("Anos únicos no dataframe de treino:", sorted(df_train["NU_ANO_CENSO"].unique().tolist()))

"""**10) Geração das sequências de validação (histórico combinado e alvos no período de validação)**

Criar as sequências de validação utilizando a função *build_sequences()*.
Para isso, concatena-se os dados de treino e validação em *df_hist_for_val*, permitindo assim que o modelo use todo o histórico anterior (2014–2020) como base para prever os anos de validação (2021–2022).
O resultado são três estruturas:


*   *X_val* → janelas históricas de entrada;
*   *y_val* → valores reais da evasão no período de validação;
*   *meta_val* → metadados com ano previsto e chaves de agrupamento (*GROUP_KEYS*).
"""

# Para VALIDAÇÃO: alvos nos anos de validação; histórico (treino + validação)
df_hist_for_val = pd.concat([df_train, df_val], axis=0, ignore_index=True)
X_val, y_val, meta_val = build_sequences(
    df_all_history=df_hist_for_val,
    df_target_years=df_val,
    history_window=HISTORY_WINDOW,
    forecast_h=FORECAST_H,
    group_keys=GROUP_KEYS,
    features=FEATURES
)

"""**11) Verificação das dimensões das sequências de treino e validação**

Exibir um resumo quantitativo das sequências geradas para treino e validação, mostra o número total de amostras criadas em *X_train* e *X_val*, bem como a quantidade de variáveis de entrada (*num_features*) e o tamanho da janela temporal utilizada (*seq_len = HISTORY_WINDOW*).

Utlizado como checagem final antes da modelagem, confirmando que as janelas e os dados de entrada foram gerados corretamente.
"""

print(f"Sequências geradas — Treino: {len(X_train)} | Validação: {len(X_val)}")
num_features = len(FEATURES)
seq_len = HISTORY_WINDOW
print("Num features:", num_features, "| seq_len:", seq_len)

"""**12) Definição e inicialização do modelo LSTM para previsão da taxa de evasão**

Implementar a classe *LSTMEvasao*, um modelo baseado em redes recorrentes LSTM para previsão de séries temporais de evasão.
A arquitetura utiliza camadas LSTM para capturar padrões temporais e uma cabeça densa (*head*) com camadas lineares e função de ativação ReLU para gerar a saída contínua da taxa de evasão (*TAXA_EVASAO*).

O modelo é configurado com:


*   *input_size = num_features* : número de variáveis de entrada;
*   *hidden_size = 64* : número de neurônios na camada oculta;
*   *num_layers = 2* : duas camadas LSTM empilhadas;
*   *dropout = 0.2* : regularização para evitar overfitting.

Ao final, o modelo é instanciado e transferido para GPU (cuda) se disponível, sendo exibida sua estrutura completa.
"""

#  CONSTRUÇÃO DO MODELO
class LSTMEvasao(nn.Module):
    def __init__(self, input_size, hidden_size=64, num_layers=2, dropout=0.2):
        super().__init__()
        self.lstm = nn.LSTM(
            input_size=input_size,
            hidden_size=hidden_size,
            num_layers=num_layers,
            batch_first=True,
            dropout=dropout
        )
        self.head = nn.Sequential(
            nn.Linear(hidden_size, hidden_size),
            nn.ReLU(),
            nn.Linear(hidden_size, 1)   # saída: taxa de evasão (regressão)
        )

    def forward(self, x):
        # x: [batch, seq_len, input_size]
        out, (h_n, c_n) = self.lstm(x)     # h_n: [num_layers, batch, hidden]
        h_last = h_n[-1]                   # [batch, hidden]
        y_hat = self.head(h_last).squeeze(-1)  # [batch]
        return y_hat

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model = LSTMEvasao(input_size=num_features, hidden_size=64, num_layers=2, dropout=0.2).to(device)
print(model)

"""**13) Empacotamento dos dados, treinamento do modelo e aplicação de early stopping**

Converter as listas de sequências (*X_train`, *y_train*, *X_val*, *y_val*) em tensores PyTorch por meio da função *to_tensors()*, criando conjuntos (*TensorDataset*) e carregadores de dados (*DataLoader*) para treino e validação.

Em seguida, define os elementos fundamentais do treinamento:

*   Função de perda: *MSELoss()* (erro quadrático médio);
*   Otimizador: *Adam* com taxa de aprendizado *1e-3* e regularização *weight_decay*;
*   Critérios de parada antecipada (early stopping) com *patience = 5* e até *EPOCHS = 30*.


Durante o loop de treinamento:


*   O modelo é treinado (*model.train()*) e avaliado (*model.eval()*) a cada época;
*   As perdas médias de treino e validação são exibidas;
*   Se o erro de validação (val_loss) melhora, o melhor estado do modelo é salvo;
*   Caso contrário, o treinamento é interrompido automaticamente após *patience* épocas sem melhora.

Por fim, o melhor modelo (menor erro de validação) é recarregado em memória, garantindo que as próximas etapas usem o modelo mais estável e preciso.
"""

# Empacotar dados em DataLoader
def to_tensors(X_list, y_list):
    X = np.stack(X_list, axis=0)  # [N, seq_len, num_features]
    y = np.array(y_list, dtype=np.float32)  # [N]
    X_t = torch.tensor(X, dtype=torch.float32)
    y_t = torch.tensor(y, dtype=torch.float32)
    return X_t, y_t

Xtr_t, ytr_t = to_tensors(X_train, y_train)
Xva_t, yva_t = to_tensors(X_val, y_val)

train_ds = TensorDataset(Xtr_t, ytr_t)
val_ds   = TensorDataset(Xva_t, yva_t)

train_dl = DataLoader(train_ds, batch_size=256, shuffle=True, drop_last=False)
val_dl   = DataLoader(val_ds, batch_size=256, shuffle=False, drop_last=False)

# Perda, otimizador, early stopping
criterion = torch.nn.MSELoss()
optimizer = torch.optim.Adam(model.parameters(), lr=1e-3, weight_decay=1e-5)

best_val = float("inf")
patience = 5
wait = 0
best_state = None
EPOCHS = 30

for epoch in range(1, EPOCHS+1):
    # --- treino ---
    model.train()
    train_loss = 0.0
    # Adicionar tqdm para a barra de progresso no treino
    for xb, yb in tqdm(train_dl, desc=f"Epoch {epoch:02d} [Treino]"):
        xb, yb = xb.to(device), yb.to(device)
        optimizer.zero_grad()
        preds = model(xb)
        loss = criterion(preds, yb)
        loss.backward()
        optimizer.step()
        train_loss += loss.item() * xb.size(0)
    train_loss /= len(train_dl.dataset)

    # validação
    model.eval()
    val_loss = 0.0
    with torch.no_grad():
        # Adicionar tqdm para a barra de progresso na validação
        for xb, yb in tqdm(val_dl, desc=f"Epoch {epoch:02d} [Validação]"):
            xb, yb = xb.to(device), yb.to(device)
            preds = model(xb)
            loss = criterion(preds, yb)
            val_loss += loss.item() * xb.size(0)
    val_loss /= len(val_dl.dataset)

    print(f"Época {epoch:02d} | train MSE: {train_loss:.6f} | val MSE: {val_loss:.6f}")

    # early stopping
    if val_loss < best_val - 1e-6:
        best_val = val_loss
        best_state = {k: v.cpu().clone() for k, v in model.state_dict().items()}
        wait = 0
    else:
        wait += 1
        if wait >= patience:
            print(" Early stopping acionado.")
            break

# Carregar melhor estado
if best_state is not None:
    model.load_state_dict(best_state)
    model.to(device)
    print(f" Melhor val MSE: {best_val:.6f}")

"""**14) Avaliação do modelo na base de validação e cálculo das métricas de desempenho**

Realizar a avaliação final do modelo LSTM sobre o conjunto de validação, sem gradientes (*torch.no_grad()*), para evitar atualizações nos pesos.
As predições (*y_pred_val*) são geradas lote a lote a partir de *val_dl*, e comparadas com os valores reais (*y_true_val*).

Em seguida, são calculadas três métricas de desempenho:

*   *MAE* — Erro Absoluto Médio, mede a média dos desvios absolutos entre valores reais e previstos;
*   *RMSE* — Raiz do Erro Quadrático Médio, penaliza mais fortemente grandes erros;
*   *R²* — Coeficiente de Determinação, indica o quanto o modelo explica da variabilidade dos dados (quanto mais próximo de 1, melhor).

Por fim, os resultados são impressos para avaliar a precisão do modelo na etapa de validação.
"""

model.eval()
with torch.no_grad():
    y_pred_val = []
    for xb, yb in val_dl:
        xb = xb.to(device)
        preds = model(xb).cpu().numpy()
        y_pred_val.append(preds)
    y_pred_val = np.concatenate(y_pred_val, axis=0)

y_true_val = yva_t.numpy()

# --- Métricas ---
def mae(y, yhat): return float(np.mean(np.abs(y - yhat)))
def rmse(y, yhat): return float(sqrt(np.mean((y - yhat)**2)))
def r2(y, yhat):
    ss_res = np.sum((y - yhat)**2)
    ss_tot = np.sum((y - np.mean(y))**2)
    return float(1 - ss_res/ss_tot) if ss_tot > 0 else float("nan")

print(f"Val MAE : {mae(y_true_val, y_pred_val):.6f}")
print(f"Val RMSE: {rmse(y_true_val, y_pred_val):.6f}")
print(f"Val R^2 : {r2(y_true_val, y_pred_val):.6f}")

"""**15) Visualização da relação entre valores reais e previstos (dispersão)**

Gerar um gráfico de dispersão comparando os valores reais (*y_true_val*) e previstos (*y_pred_val*) da taxa de evasão.

Cada ponto representa uma observação da base de validação, permitindo visualizar a precisão do modelo — quanto mais próximos da linha diagonal (0–1) os pontos estiverem, melhor o desempenho preditivo.

O gráfico é configurado com rótulos claros, grade, e tamanho ajustado para análise visual direta da correlação entre predições e valores reais.
"""

# --- Gráfico 1: Dispersão y_true vs y_pred ---
plt.figure(figsize=(6,6))
plt.scatter(y_true_val, y_pred_val, alpha=0.3, s=8)
plt.plot([0,1],[0,1])
plt.title("Validação: y verdadeiro vs y predito")
plt.xlabel("Taxa de evasão (real)")
plt.ylabel("Taxa de evasão (prevista)")
plt.grid(True, linestyle="--", alpha=0.6)
plt.tight_layout()
plt.show()

"""**16) Geração das curvas anuais médias de evasão (real x previsto) por modalidade**

Criar um gráfico temporal comparando as taxas médias de evasão reais e previstas, separadas por modalidade de ensino (0 = presencial, 1 = EAD).

O processo envolverá:

1.   Reconstrução do DataFrame de metadados (*val_meta_df*) a partir de *meta_val*, unindo os valores reais (*y_true_val*) e previstos (*y_pred_val*).
2.   Extração da modalidade do tuple *group_keys* (índice 2) e cálculo das médias por ano e modalidade.
3.   Criação de tabelas dinâmicas (*pivot_true* e *pivot_pred*) para facilitar a comparação visual.
4.   Plotagem das curvas — linhas sólidas representam valores reais e linhas tracejadas as previsões do modelo.

O gráfico permitirá visualizar tendências de evasão ao longo dos anos e avaliar a aderência do modelo em diferentes modalidades de ensino.
"""

# --- Gráfico 2: Curvas anuais agregadas por modalidade (0/1) ---
# Precisamos resgatar os metadados (anos alvo) e modalidades correspondentes às sequências de val.
# meta_val tem target_year e group_keys = (CO_IES, CO_CINE_ROTULO_id, Modalidade)
val_meta_df = pd.DataFrame(meta_val)
val_meta_df["y_true"] = y_true_val
val_meta_df["y_pred"] = y_pred_val

# extrair Modalidade do tuple group_keys (índice 2)
val_meta_df["Modalidade"] = val_meta_df["group_keys"].apply(lambda t: t[2])

# Agregar por ano e modalidade
agg_val = (
    val_meta_df
    .groupby(["target_year", "Modalidade"], as_index=False)
    .agg(y_true_mean=("y_true","mean"), y_pred_mean=("y_pred","mean"))
    .sort_values(["target_year","Modalidade"])
)

# Pivot para duas linhas por modalidade
pivot_true = agg_val.pivot(index="target_year", columns="Modalidade", values="y_true_mean")
pivot_pred = agg_val.pivot(index="target_year", columns="Modalidade", values="y_pred_mean")

plt.figure(figsize=(10,6))
for mod in [0,1]:
    if mod in pivot_true.columns:
        plt.plot(pivot_true.index, pivot_true[mod].values, marker="o", linewidth=2, label=f"Real - Modalidade {mod}")
    if mod in pivot_pred.columns:
        plt.plot(pivot_pred.index, pivot_pred[mod].values, marker="o", linewidth=2, linestyle="--", label=f"Previsto - Modalidade {mod}")



"""**17) Configuração e exibição final do gráfico de evasão por ano e modalidade**

Finalizar a formatação e exibição do gráfico que compara as taxas médias de evasão reais e previstas por modalidade.

Definir o título, os rótulos dos eixos, a grade e a legenda, além de ajustar o layout para melhor visualização (*tight_layout()*).

Por fim, o comando *plt.show()* exibirá o gráfico completo, permitindo analisar visualmente a precisão temporal do modelo e as diferenças entre modalidades presenciais e EAD.
"""

plt.title("Validação: Taxa média de evasão por ano e modalidade")
plt.xlabel("Ano do Censo")
plt.ylabel("Taxa de evasão média")
plt.grid(True, linestyle="--", alpha=0.6)
plt.legend()
plt.tight_layout()
